-- Banking: immutable deposit history; manual cleared/reconciled line states.
CREATE VIEW banking_register_account AS SELECT a.* FROM ledger_account a WHERE a.detail_type IN ('BANK','CREDIT_CARD') OR EXISTS(SELECT 1 FROM documents_designatedbank b JOIN documents_accountingsetup s ON s.id=b.setup_id WHERE b.account_id=a.id AND s.company_id=a.company_id);
CREATE TABLE banking_deposit(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES ledger_company(id) DEFERRABLE INITIALLY DEFERRED,identity_id TEXT NOT NULL UNIQUE REFERENCES documents_documentidentity(id) DEFERRABLE INITIALLY DEFERRED,bank_id TEXT NOT NULL REFERENCES ledger_account(id) DEFERRABLE INITIALLY DEFERRED,journal_id TEXT NOT NULL UNIQUE REFERENCES ledger_journal(id) DEFERRABLE INITIALLY DEFERRED,date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount BETWEEN 1 AND 9999999999999999),data TEXT NOT NULL CHECK(json_valid(data)),actor_id TEXT NOT NULL REFERENCES fb_user(id) DEFERRABLE INITIALLY DEFERRED) WITHOUT ROWID, STRICT;
CREATE TABLE banking_depositline(id TEXT PRIMARY KEY,deposit_id TEXT NOT NULL REFERENCES banking_deposit(id) DEFERRABLE INITIALLY DEFERRED,receipt_id TEXT NOT NULL REFERENCES sales_receipt(id) DEFERRABLE INITIALLY DEFERRED,undeposited_id TEXT NOT NULL REFERENCES ledger_account(id) DEFERRABLE INITIALLY DEFERRED,amount INTEGER NOT NULL CHECK(amount BETWEEN 1 AND 9999999999999999),UNIQUE(deposit_id,receipt_id)) WITHOUT ROWID, STRICT;
CREATE TABLE banking_depositreversal(id TEXT PRIMARY KEY,deposit_id TEXT NOT NULL UNIQUE REFERENCES banking_deposit(id) DEFERRABLE INITIALLY DEFERRED,journal_id TEXT NOT NULL UNIQUE REFERENCES ledger_journal(id) DEFERRABLE INITIALLY DEFERRED,date TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),actor_id TEXT NOT NULL REFERENCES fb_user(id) DEFERRABLE INITIALLY DEFERRED) WITHOUT ROWID, STRICT;
CREATE TABLE banking_reconciliation(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES ledger_company(id) DEFERRABLE INITIALLY DEFERRED,account_id TEXT NOT NULL REFERENCES ledger_account(id) DEFERRABLE INITIALLY DEFERRED,status TEXT NOT NULL CHECK(status IN('OPEN','DONE','UNDONE')),statement_date TEXT NOT NULL CHECK(statement_date BETWEEN '1900-01-02' AND '9999-12-30' AND date(statement_date)=statement_date),ending_balance INTEGER NOT NULL CHECK(ending_balance BETWEEN -9999999999999999 AND 9999999999999999),hide_later INTEGER NOT NULL CHECK(hide_later IN(0,1)),request_key TEXT NOT NULL,creation_digest TEXT NOT NULL CHECK(length(creation_digest)=64),revision INTEGER NOT NULL CHECK(revision>=1),data TEXT NOT NULL CHECK(json_valid(data)),started_by_id TEXT NOT NULL REFERENCES fb_user(id) DEFERRABLE INITIALLY DEFERRED,UNIQUE(company_id,request_key)) WITHOUT ROWID, STRICT;
CREATE UNIQUE INDEX reconciliation_one_open_per_account ON banking_reconciliation(account_id) WHERE status='OPEN';
CREATE TABLE banking_banklinestatus(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES ledger_company(id) DEFERRABLE INITIALLY DEFERRED,journal_line_id TEXT NOT NULL UNIQUE REFERENCES ledger_journalline(id) DEFERRABLE INITIALLY DEFERRED,account_id TEXT NOT NULL REFERENCES ledger_account(id) DEFERRABLE INITIALLY DEFERRED,state TEXT NOT NULL CHECK(state IN('U','C','R')),revision INTEGER NOT NULL CHECK(revision>=1),changed_by_id TEXT NOT NULL REFERENCES fb_user(id) DEFERRABLE INITIALLY DEFERRED,reconciliation_id TEXT REFERENCES banking_reconciliation(id) DEFERRABLE INITIALLY DEFERRED,CHECK((state='R' AND reconciliation_id IS NOT NULL) OR (state<>'R' AND reconciliation_id IS NULL))) WITHOUT ROWID, STRICT;
CREATE INDEX bank_line_status_account ON banking_banklinestatus(account_id,state);
CREATE TABLE banking_reconciliationline(id TEXT PRIMARY KEY,reconciliation_id TEXT NOT NULL REFERENCES banking_reconciliation(id) DEFERRABLE INITIALLY DEFERRED,journal_line_id TEXT NOT NULL REFERENCES ledger_journalline(id) DEFERRABLE INITIALLY DEFERRED,debit INTEGER NOT NULL CHECK(debit BETWEEN 0 AND 9999999999999999),credit INTEGER NOT NULL CHECK(credit BETWEEN 0 AND 9999999999999999),UNIQUE(reconciliation_id,journal_line_id)) WITHOUT ROWID, STRICT;
CREATE TABLE banking_seal(kind TEXT NOT NULL CHECK(kind IN('deposit','journal','reconciliation')),doc_id TEXT NOT NULL,PRIMARY KEY(kind,doc_id)) WITHOUT ROWID, STRICT;
CREATE TABLE banking_seal_due(kind TEXT NOT NULL,doc_id TEXT NOT NULL,PRIMARY KEY(kind,doc_id),FOREIGN KEY(kind,doc_id) REFERENCES banking_seal(kind,doc_id) DEFERRABLE INITIALLY DEFERRED) WITHOUT ROWID, STRICT;

CREATE TRIGGER fb_banking_deposit_scope BEFORE INSERT ON banking_deposit BEGIN
 SELECT RAISE(ABORT,'deposit_scope: Invalid deposit ownership/posting') WHERE NOT EXISTS(SELECT 1 FROM documents_documentidentity i JOIN ledger_journal j ON j.source_id=i.id JOIN ledger_account a ON a.id=NEW.bank_id JOIN documents_designatedbank b ON b.account_id=a.id JOIN documents_accountingsetup s ON s.id=b.setup_id WHERE i.id=NEW.identity_id AND i.company_id=NEW.company_id AND i.kind='DEP' AND a.company_id=NEW.company_id AND a.kind='ASSET' AND a.active=1 AND a.postable=1 AND s.company_id=NEW.company_id AND j.id=NEW.journal_id AND j.company_id=NEW.company_id AND j.status='POSTED' AND j.reversal_of_id IS NULL AND j.date=NEW.date);
 SELECT RAISE(ABORT,'deposit_fields: Invalid deposit fields') WHERE json_extract(NEW.data,'$.id') IS NOT NEW.id OR json_extract(NEW.data,'$.company_id') IS NOT NEW.company_id OR json_extract(NEW.data,'$.identity_id') IS NOT NEW.identity_id OR json_extract(NEW.data,'$.journal_id') IS NOT NEW.journal_id OR json_extract(NEW.data,'$.bank_id') IS NOT NEW.bank_id OR json_extract(NEW.data,'$.date') IS NOT NEW.date OR fb_banking_money(json_quote(json_extract(NEW.data,'$.amount'))) IS NOT NEW.amount OR length(json_extract(NEW.data,'$.creation_digest')) IS NOT 64 OR length(json_extract(NEW.data,'$.review_digest')) IS NOT 64 OR length(json_extract(NEW.data,'$.memo'))>2000 OR length(json_extract(NEW.data,'$.reference'))>120 OR NOT EXISTS(SELECT 1 FROM fb_user WHERE id=NEW.actor_id);
END;
CREATE TRIGGER fb_banking_deposit_due AFTER INSERT ON banking_deposit BEGIN INSERT INTO banking_seal_due VALUES('deposit',NEW.id); END;
CREATE TRIGGER fb_banking_line_scope BEFORE INSERT ON banking_depositline BEGIN
 SELECT RAISE(ABORT,'deposit_late_membership: Cannot append to committed deposit membership') WHERE NOT EXISTS(SELECT 1 FROM banking_deposit WHERE id=NEW.deposit_id) OR EXISTS(SELECT 1 FROM banking_seal WHERE kind='deposit' AND doc_id=NEW.deposit_id);
 SELECT RAISE(ABORT,'deposit_line_scope: Invalid deposit membership target') WHERE NOT EXISTS(SELECT 1 FROM banking_deposit d JOIN sales_receipt r ON r.id=NEW.receipt_id JOIN ledger_account a ON a.id=NEW.undeposited_id WHERE d.id=NEW.deposit_id AND r.company_id=d.company_id AND r.destination='UNDEPOSITED' AND r.destination_account_id=NEW.undeposited_id AND r.amount=NEW.amount AND r.date<=d.date AND NEW.undeposited_id<>d.bank_id AND a.kind='ASSET' AND a.company_id=d.company_id AND a.active=1 AND a.postable=1 AND NOT EXISTS(SELECT 1 FROM sales_receiptreversal WHERE receipt_id=r.id));
 SELECT RAISE(ABORT,'deposit_unique_live_membership: Receipt already belongs to a live deposit') WHERE EXISTS(SELECT 1 FROM banking_depositline l WHERE l.receipt_id=NEW.receipt_id AND NOT EXISTS(SELECT 1 FROM banking_depositreversal z WHERE z.deposit_id=l.deposit_id));
 SELECT RAISE(ABORT,'deposit_line_release_date: Deposit cannot be dated before the receipt was released from an earlier deposit') WHERE (SELECT date FROM banking_deposit WHERE id=NEW.deposit_id)<(SELECT max(z.date) FROM banking_depositline l JOIN banking_depositreversal z ON z.deposit_id=l.deposit_id WHERE l.receipt_id=NEW.receipt_id);
END;
CREATE TRIGGER fb_banking_reversal_scope BEFORE INSERT ON banking_depositreversal BEGIN
 SELECT RAISE(ABORT,'deposit_reversal_link: Invalid deposit reversal') WHERE NOT EXISTS(SELECT 1 FROM banking_deposit d JOIN ledger_journal j ON j.id=NEW.journal_id WHERE d.id=NEW.deposit_id AND j.source_id=d.identity_id AND j.company_id=d.company_id AND j.status='POSTED' AND j.reversal_of_id=d.journal_id AND j.date=NEW.date AND NEW.date>=d.date AND length(trim(json_extract(NEW.data,'$.reason'))) BETWEEN 1 AND 500 AND json_extract(NEW.data,'$.id')=NEW.id AND json_extract(NEW.data,'$.deposit_id')=NEW.deposit_id AND json_extract(NEW.data,'$.journal_id')=NEW.journal_id AND json_extract(NEW.data,'$.date')=NEW.date AND EXISTS(SELECT 1 FROM fb_user WHERE id=NEW.actor_id));
END;
CREATE TRIGGER fb_banking_receipt_live_deposit BEFORE INSERT ON sales_receiptreversal BEGIN
 SELECT RAISE(ABORT,'receipt_live_deposit: Reverse the live deposit before reversing this receipt') WHERE EXISTS(SELECT 1 FROM banking_depositline l WHERE l.receipt_id=NEW.receipt_id AND NOT EXISTS(SELECT 1 FROM banking_depositreversal z WHERE z.deposit_id=l.deposit_id));
 SELECT RAISE(ABORT,'receipt_release_date: Receipt reversal cannot be dated before the receipt was released from its deposit') WHERE NEW.date<(SELECT max(z.date) FROM banking_depositline l JOIN banking_depositreversal z ON z.deposit_id=l.deposit_id WHERE l.receipt_id=NEW.receipt_id);
END;
CREATE TRIGGER fb_banking_reversal_cleared BEFORE INSERT ON ledger_journal BEGIN
 SELECT RAISE(ABORT,'bank_line_cleared_reversal: A journal with a cleared bank line cannot be reversed') WHERE NEW.reversal_of_id IS NOT NULL AND EXISTS(SELECT 1 FROM banking_banklinestatus s JOIN ledger_journalline l ON l.id=s.journal_line_id WHERE l.journal_id=NEW.reversal_of_id AND s.state IN('C','R'));
END;
CREATE TRIGGER fb_banking_journal_due AFTER INSERT ON ledger_journal WHEN (SELECT kind FROM documents_documentidentity WHERE id=NEW.source_id)='DEP' BEGIN INSERT INTO banking_seal_due VALUES('journal',NEW.id); END;
CREATE TRIGGER fb_banking_late_reference BEFORE INSERT ON documents_documentaccount BEGIN
 SELECT RAISE(ABORT,'deposit_late_reference: Cannot append account evidence to a committed deposit') WHERE EXISTS(SELECT 1 FROM banking_deposit d JOIN banking_seal s ON s.kind='deposit' AND s.doc_id=d.id WHERE d.identity_id=NEW.source_id);
END;

CREATE VIEW banking_deposit_expected AS
 SELECT d.id deposit_id,d.bank_id account_id,d.amount debit,0 credit FROM banking_deposit d
 UNION ALL SELECT l.deposit_id,l.undeposited_id,0,fb_banking_sum(json_group_array(l.amount)) FROM banking_depositline l GROUP BY l.deposit_id,l.undeposited_id;
CREATE VIEW banking_deposit_invalid AS SELECT d.id FROM banking_deposit d WHERE
 (SELECT count(*) FROM banking_depositline WHERE deposit_id=d.id) NOT BETWEEN 1 AND 50 OR
 d.amount<>fb_banking_sum((SELECT json_group_array(amount) FROM banking_depositline WHERE deposit_id=d.id)) OR
 EXISTS(SELECT account_id,debit,credit FROM banking_deposit_expected WHERE deposit_id=d.id EXCEPT SELECT account_id,debit,credit FROM ledger_journalline WHERE journal_id=d.journal_id) OR
 EXISTS(SELECT account_id,debit,credit FROM ledger_journalline WHERE journal_id=d.journal_id EXCEPT SELECT account_id,debit,credit FROM banking_deposit_expected WHERE deposit_id=d.id) OR
 (SELECT count(*) FROM ledger_journalline WHERE journal_id=d.journal_id)<>(SELECT count(*) FROM banking_deposit_expected WHERE deposit_id=d.id) OR
 EXISTS(SELECT 1 FROM banking_depositline l WHERE l.deposit_id=d.id AND NOT EXISTS(SELECT 1 FROM documents_documentaccount a WHERE a.source_id=d.identity_id AND a.role='undeposited:'||l.undeposited_id AND a.account_id=l.undeposited_id)) OR
 NOT EXISTS(SELECT 1 FROM documents_documentaccount a WHERE a.source_id=d.identity_id AND a.role='bank' AND a.account_id=d.bank_id) OR
 (SELECT count(*) FROM documents_documentaccount a WHERE a.source_id=d.identity_id)<>(SELECT count(*) FROM banking_deposit_expected WHERE deposit_id=d.id);

CREATE TRIGGER fb_banking_rec_insert BEFORE INSERT ON banking_reconciliation BEGIN
 SELECT RAISE(ABORT,'reconciliation_insert: A reconciliation starts open at revision 1') WHERE NEW.status<>'OPEN' OR NEW.revision<>1;
 SELECT RAISE(ABORT,'reconciliation_account: Only bank and credit card accounts of the company are reconciled') WHERE NOT EXISTS(SELECT 1 FROM banking_register_account WHERE id=NEW.account_id AND company_id=NEW.company_id AND active=1) OR NOT EXISTS(SELECT 1 FROM fb_user WHERE id=NEW.started_by_id);
END;
CREATE TRIGGER fb_banking_rec_fields_insert BEFORE INSERT ON banking_reconciliation BEGIN
 SELECT RAISE(ABORT,'reconciliation_fields: Invalid reconciliation fields') WHERE json_extract(NEW.data,'$.id') IS NOT NEW.id OR json_extract(NEW.data,'$.company_id') IS NOT NEW.company_id OR json_extract(NEW.data,'$.account_id') IS NOT NEW.account_id OR json_extract(NEW.data,'$.request_key') IS NOT NEW.request_key OR json_extract(NEW.data,'$.creation_digest') IS NOT NEW.creation_digest OR json_extract(NEW.data,'$.revision') IS NOT NEW.revision OR json_extract(NEW.data,'$.status') IS NOT NEW.status OR json_extract(NEW.data,'$.statement_date') IS NOT NEW.statement_date OR fb_banking_money(json_quote(json_extract(NEW.data,'$.ending_balance'))) IS NOT NEW.ending_balance OR json_extract(NEW.data,'$.hide_later') IS NOT NEW.hide_later OR json_extract(NEW.data,'$.completion_key') IS NOT NULL OR json_extract(NEW.data,'$.undo_key') IS NOT NULL;
 SELECT RAISE(ABORT,'reconciliation_statement_order: The statement date is before the last reconciled statement') WHERE EXISTS(SELECT 1 FROM banking_reconciliation WHERE account_id=NEW.account_id AND status='DONE' AND statement_date>NEW.statement_date);
END;
CREATE TRIGGER fb_banking_rec_update BEFORE UPDATE ON banking_reconciliation BEGIN
 SELECT RAISE(ABORT,'reconciliation_identity: A reconciliation keeps its company, account and origin') WHERE NEW.company_id IS NOT OLD.company_id OR NEW.account_id IS NOT OLD.account_id OR NEW.request_key IS NOT OLD.request_key OR NEW.creation_digest IS NOT OLD.creation_digest OR NEW.started_by_id IS NOT OLD.started_by_id OR json_extract(NEW.data,'$.started_by') IS NOT json_extract(OLD.data,'$.started_by');
 SELECT RAISE(ABORT,'reconciliation_revision: Reconciliation revision must step by one') WHERE OLD.revision=9223372036854775807 OR NEW.revision<>OLD.revision+1;
 SELECT RAISE(ABORT,'reconciliation_final: An undone reconciliation is final') WHERE OLD.status='UNDONE';
 SELECT RAISE(ABORT,'reconciliation_undo_open: Only a completed reconciliation can be undone') WHERE OLD.status='OPEN' AND NEW.status='UNDONE';
 SELECT RAISE(ABORT,'reconciliation_done_locked: A completed reconciliation changes only by Undo last') WHERE OLD.status='DONE' AND (NEW.status<>'UNDONE' OR NEW.statement_date IS NOT OLD.statement_date OR NEW.ending_balance IS NOT OLD.ending_balance OR NEW.hide_later IS NOT OLD.hide_later OR json_remove(NEW.data,'$.status','$.revision','$.undone_by','$.undo_key','$.undo_reason') IS NOT json_remove(OLD.data,'$.status','$.revision','$.undone_by','$.undo_key','$.undo_reason'));
 SELECT RAISE(ABORT,'reconciliation_undo_last: Only the most recent reconciliation of an account can be undone') WHERE OLD.status='DONE' AND EXISTS(SELECT 1 FROM banking_reconciliation r WHERE r.account_id=OLD.account_id AND r.status='DONE' AND r.id>OLD.id);
 SELECT RAISE(ABORT,'reconciliation_fields: Invalid reconciliation fields') WHERE json_extract(NEW.data,'$.id') IS NOT NEW.id OR json_extract(NEW.data,'$.company_id') IS NOT NEW.company_id OR json_extract(NEW.data,'$.account_id') IS NOT NEW.account_id OR json_extract(NEW.data,'$.request_key') IS NOT NEW.request_key OR json_extract(NEW.data,'$.creation_digest') IS NOT NEW.creation_digest OR json_extract(NEW.data,'$.revision') IS NOT NEW.revision OR json_extract(NEW.data,'$.status') IS NOT NEW.status OR json_extract(NEW.data,'$.statement_date') IS NOT NEW.statement_date OR fb_banking_money(json_quote(json_extract(NEW.data,'$.ending_balance'))) IS NOT NEW.ending_balance OR json_extract(NEW.data,'$.hide_later') IS NOT NEW.hide_later;
 SELECT RAISE(ABORT,'reconciliation_statement_order: The statement date is before the last reconciled statement') WHERE OLD.status='OPEN' AND EXISTS(SELECT 1 FROM banking_reconciliation WHERE account_id=NEW.account_id AND status='DONE' AND statement_date>NEW.statement_date);
 SELECT RAISE(ABORT,'reconciliation_beginning: The beginning balance must be the last reconciled ending balance') WHERE OLD.status='OPEN' AND NEW.status='DONE' AND fb_banking_money(json_quote(json_extract(NEW.data,'$.beginning_balance'))) IS NOT coalesce((SELECT ending_balance FROM banking_reconciliation WHERE account_id=NEW.account_id AND status='DONE' ORDER BY id DESC LIMIT 1),0);
END;
CREATE TRIGGER fb_banking_rec_due_insert AFTER INSERT ON banking_reconciliation BEGIN INSERT INTO banking_seal_due VALUES('reconciliation',NEW.id||':'||NEW.revision); END;
CREATE TRIGGER fb_banking_rec_due_update AFTER UPDATE ON banking_reconciliation BEGIN INSERT INTO banking_seal_due SELECT 'reconciliation',NEW.id||':'||NEW.revision WHERE NOT EXISTS(SELECT 1 FROM banking_seal_due WHERE kind='reconciliation' AND doc_id=NEW.id||':'||NEW.revision); END;
CREATE TRIGGER fb_banking_rec_line_scope BEFORE INSERT ON banking_reconciliationline BEGIN
 SELECT RAISE(ABORT,'reconciliation_line_insert: A reconciliation line records a cleared posted line of its account while the reconciliation completes') WHERE NOT EXISTS(SELECT 1 FROM banking_reconciliation r JOIN ledger_journalline l ON l.id=NEW.journal_line_id JOIN ledger_journal j ON j.id=l.journal_id JOIN banking_banklinestatus s ON s.journal_line_id=l.id WHERE r.id=NEW.reconciliation_id AND r.status='OPEN' AND j.status='POSTED' AND j.company_id=r.company_id AND l.account_id=r.account_id AND l.debit=NEW.debit AND l.credit=NEW.credit AND s.state='C' AND (r.hide_later=0 OR j.date<=r.statement_date));
 -- Every membership insertion obliges completion in the same transaction.
END;
CREATE TRIGGER fb_banking_rec_line_due AFTER INSERT ON banking_reconciliationline BEGIN INSERT INTO banking_seal_due SELECT 'reconciliation',r.id||':'||(r.revision+1) FROM banking_reconciliation r WHERE r.id=NEW.reconciliation_id AND NOT EXISTS(SELECT 1 FROM banking_seal_due WHERE kind='reconciliation' AND doc_id=r.id||':'||(r.revision+1)); END;
CREATE TRIGGER fb_banking_status_insert BEFORE INSERT ON banking_banklinestatus BEGIN
 SELECT RAISE(ABORT,'bank_line_status_revision: A new bank line status starts at revision 1') WHERE NEW.revision<>1;
 SELECT RAISE(ABORT,'bank_line_status_reconciled: Reconciled marks change only through Reconcile') WHERE NEW.state='R';
 SELECT RAISE(ABORT,'bank_line_status_line: Cleared status needs a posted line of this company on this account') WHERE NOT EXISTS(SELECT 1 FROM ledger_journalline l JOIN ledger_journal j ON j.id=l.journal_id JOIN banking_register_account a ON a.id=l.account_id WHERE l.id=NEW.journal_line_id AND j.status='POSTED' AND j.company_id=NEW.company_id AND l.account_id=NEW.account_id AND a.company_id=NEW.company_id) OR NOT EXISTS(SELECT 1 FROM fb_user WHERE id=NEW.changed_by_id);
END;
CREATE TRIGGER fb_banking_status_update BEFORE UPDATE ON banking_banklinestatus BEGIN
 SELECT RAISE(ABORT,'bank_line_status_identity: A bank line status keeps its line, company and account') WHERE NEW.company_id IS NOT OLD.company_id OR NEW.journal_line_id IS NOT OLD.journal_line_id OR NEW.account_id IS NOT OLD.account_id;
 SELECT RAISE(ABORT,'bank_line_status_revision: Bank line status revision must step by one') WHERE OLD.revision=9223372036854775807 OR NEW.revision<>OLD.revision+1;
 SELECT RAISE(ABORT,'bank_line_status_reconciled: Reconciled marks change only through Reconcile') WHERE NEW.state='R' AND (OLD.state<>'C' OR NOT EXISTS(SELECT 1 FROM banking_reconciliation r JOIN banking_reconciliationline x ON x.reconciliation_id=r.id WHERE x.journal_line_id=NEW.journal_line_id AND r.id=NEW.reconciliation_id AND r.company_id=NEW.company_id AND r.account_id=NEW.account_id AND r.status='DONE' AND NOT EXISTS(SELECT 1 FROM banking_seal WHERE kind='reconciliation' AND doc_id=r.id||':'||r.revision)));
 SELECT RAISE(ABORT,'bank_line_status_undo_last: Only undoing the last reconciliation returns its lines to cleared') WHERE OLD.state='R' AND (NEW.state<>'C' OR NEW.reconciliation_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM banking_reconciliation r WHERE r.id=OLD.reconciliation_id AND r.status='UNDONE' AND NOT EXISTS(SELECT 1 FROM banking_seal WHERE kind='reconciliation' AND doc_id=r.id||':'||r.revision)));
 SELECT RAISE(ABORT,'bank_line_status_line: Cleared status needs a posted line of this company on this account') WHERE NOT EXISTS(SELECT 1 FROM fb_user WHERE id=NEW.changed_by_id);
END;
CREATE VIEW banking_rec_invalid AS SELECT r.id FROM banking_reconciliation r WHERE
 (r.status='OPEN' AND (json_extract(r.data,'$.beginning_balance') IS NOT NULL OR json_extract(r.data,'$.completion_key') IS NOT NULL OR EXISTS(SELECT 1 FROM banking_reconciliationline WHERE reconciliation_id=r.id))) OR
 (r.status IN('DONE','UNDONE') AND (
 json_type(r.data,'$.cleared_count') IS NOT 'integer' OR json_extract(r.data,'$.cleared_count')<>(SELECT count(*) FROM banking_reconciliationline WHERE reconciliation_id=r.id) OR
 json_type(r.data,'$.completion_key') IS NOT 'text' OR json_type(r.data,'$.completed_by') IS NOT 'text' OR
 fb_banking_money(json_quote(json_extract(r.data,'$.cleared_debit'))) IS NOT fb_banking_sum((SELECT json_group_array(debit) FROM banking_reconciliationline WHERE reconciliation_id=r.id)) OR
 fb_banking_money(json_quote(json_extract(r.data,'$.cleared_credit'))) IS NOT fb_banking_sum((SELECT json_group_array(credit) FROM banking_reconciliationline WHERE reconciliation_id=r.id)) OR
 r.ending_balance IS NOT fb_banking_balance(fb_banking_money(json_quote(json_extract(r.data,'$.beginning_balance'))),fb_banking_money(json_quote(json_extract(r.data,'$.cleared_debit'))),fb_banking_money(json_quote(json_extract(r.data,'$.cleared_credit'))),(SELECT CASE WHEN kind IN('ASSET','EXPENSE') THEN 1 ELSE -1 END FROM ledger_account WHERE id=r.account_id)) OR
 (r.status='DONE' AND EXISTS(SELECT 1 FROM banking_reconciliationline l LEFT JOIN banking_banklinestatus s ON s.journal_line_id=l.journal_line_id WHERE l.reconciliation_id=r.id AND (s.state IS NOT 'R' OR s.reconciliation_id IS NOT r.id))) OR
 (r.status='UNDONE' AND (json_type(r.data,'$.undo_key') IS NOT 'text' OR length(trim(json_extract(r.data,'$.undo_reason'))) IS NULL OR length(trim(json_extract(r.data,'$.undo_reason')))=0 OR EXISTS(SELECT 1 FROM banking_banklinestatus WHERE reconciliation_id=r.id))) ));

CREATE TRIGGER fb_banking_seal_check BEFORE INSERT ON banking_seal BEGIN
 SELECT RAISE(ABORT,'deposit_complete: Incomplete deposit posting or membership') WHERE NEW.kind='deposit' AND (NOT EXISTS(SELECT 1 FROM banking_deposit WHERE id=NEW.doc_id) OR EXISTS(SELECT 1 FROM banking_deposit_invalid WHERE id=NEW.doc_id));
 SELECT RAISE(ABORT,'deposit_journal_owner: Deposit journals require a complete owning lifecycle') WHERE NEW.kind='journal' AND NOT EXISTS(SELECT 1 FROM ledger_journal j WHERE j.id=NEW.doc_id AND j.status='POSTED' AND ((j.reversal_of_id IS NULL AND EXISTS(SELECT 1 FROM banking_deposit d JOIN banking_seal s ON s.kind='deposit' AND s.doc_id=d.id WHERE d.journal_id=j.id)) OR (j.reversal_of_id IS NOT NULL AND EXISTS(SELECT 1 FROM banking_depositreversal z WHERE z.journal_id=j.id))));
 SELECT RAISE(ABORT,'reconciliation_complete: Incomplete reconciliation evidence') WHERE NEW.kind='reconciliation' AND NOT EXISTS(SELECT 1 FROM banking_reconciliation r WHERE r.id||':'||r.revision=NEW.doc_id AND NOT EXISTS(SELECT 1 FROM banking_rec_invalid v WHERE v.id=r.id));
END;
CREATE TRIGGER fb_banking_deposit_collision_insert BEFORE INSERT ON banking_deposit BEGIN SELECT RAISE(ABORT,'banking_key_collision: Protected key already exists') WHERE EXISTS(SELECT 1 FROM banking_deposit WHERE (id=NEW.id) OR (identity_id=NEW.identity_id) OR (journal_id=NEW.journal_id)); END;
CREATE TRIGGER fb_banking_deposit_primary_key_permanent BEFORE UPDATE OF id ON banking_deposit WHEN NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'primary_key_immutable: Primary keys never change'); END;
CREATE TRIGGER fb_banking_deposit_immutable_update BEFORE UPDATE ON banking_deposit BEGIN SELECT RAISE(ABORT,'banking_immutable: Banking history is immutable'); END;
CREATE TRIGGER fb_banking_deposit_kept BEFORE DELETE ON banking_deposit BEGIN SELECT RAISE(ABORT,'banking_kept: Banking history is never deleted'); END;
CREATE TRIGGER fb_banking_depositline_collision_insert BEFORE INSERT ON banking_depositline BEGIN SELECT RAISE(ABORT,'banking_key_collision: Protected key already exists') WHERE EXISTS(SELECT 1 FROM banking_depositline WHERE (id=NEW.id) OR (deposit_id=NEW.deposit_id AND receipt_id=NEW.receipt_id)); END;
CREATE TRIGGER fb_banking_depositline_primary_key_permanent BEFORE UPDATE OF id ON banking_depositline WHEN NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'primary_key_immutable: Primary keys never change'); END;
CREATE TRIGGER fb_banking_depositline_immutable_update BEFORE UPDATE ON banking_depositline BEGIN SELECT RAISE(ABORT,'banking_immutable: Banking history is immutable'); END;
CREATE TRIGGER fb_banking_depositline_kept BEFORE DELETE ON banking_depositline BEGIN SELECT RAISE(ABORT,'banking_kept: Banking history is never deleted'); END;
CREATE TRIGGER fb_banking_depositreversal_collision_insert BEFORE INSERT ON banking_depositreversal BEGIN SELECT RAISE(ABORT,'banking_key_collision: Protected key already exists') WHERE EXISTS(SELECT 1 FROM banking_depositreversal WHERE (id=NEW.id) OR (deposit_id=NEW.deposit_id) OR (journal_id=NEW.journal_id)); END;
CREATE TRIGGER fb_banking_depositreversal_primary_key_permanent BEFORE UPDATE OF id ON banking_depositreversal WHEN NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'primary_key_immutable: Primary keys never change'); END;
CREATE TRIGGER fb_banking_depositreversal_immutable_update BEFORE UPDATE ON banking_depositreversal BEGIN SELECT RAISE(ABORT,'banking_immutable: Banking history is immutable'); END;
CREATE TRIGGER fb_banking_depositreversal_kept BEFORE DELETE ON banking_depositreversal BEGIN SELECT RAISE(ABORT,'banking_kept: Banking history is never deleted'); END;
CREATE TRIGGER fb_banking_reconciliation_collision_insert BEFORE INSERT ON banking_reconciliation BEGIN SELECT RAISE(ABORT,'banking_key_collision: Protected key already exists') WHERE EXISTS(SELECT 1 FROM banking_reconciliation WHERE (id=NEW.id) OR (company_id=NEW.company_id AND request_key=NEW.request_key)); END;
CREATE TRIGGER fb_banking_reconciliation_primary_key_permanent BEFORE UPDATE OF id ON banking_reconciliation WHEN NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'primary_key_immutable: Primary keys never change'); END;
CREATE TRIGGER fb_banking_reconciliation_collision_update BEFORE UPDATE ON banking_reconciliation BEGIN SELECT RAISE(ABORT,'banking_key_collision: Update would replace an existing row') WHERE EXISTS(SELECT 1 FROM banking_reconciliation WHERE NOT (id=OLD.id) AND ((id=NEW.id) OR (company_id=NEW.company_id AND request_key=NEW.request_key) OR (NEW.status='OPEN' AND account_id=NEW.account_id AND status='OPEN'))); END;
CREATE TRIGGER fb_banking_reconciliation_kept BEFORE DELETE ON banking_reconciliation BEGIN SELECT RAISE(ABORT,'banking_kept: Banking history is never deleted'); END;
CREATE TRIGGER fb_banking_banklinestatus_collision_insert BEFORE INSERT ON banking_banklinestatus BEGIN SELECT RAISE(ABORT,'banking_key_collision: Protected key already exists') WHERE EXISTS(SELECT 1 FROM banking_banklinestatus WHERE (id=NEW.id) OR (journal_line_id=NEW.journal_line_id)); END;
CREATE TRIGGER fb_banking_banklinestatus_primary_key_permanent BEFORE UPDATE OF id ON banking_banklinestatus WHEN NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'primary_key_immutable: Primary keys never change'); END;
CREATE TRIGGER fb_banking_banklinestatus_collision_update BEFORE UPDATE ON banking_banklinestatus BEGIN SELECT RAISE(ABORT,'banking_key_collision: Update would replace an existing row') WHERE EXISTS(SELECT 1 FROM banking_banklinestatus WHERE NOT (id=OLD.id) AND ((id=NEW.id) OR (journal_line_id=NEW.journal_line_id))); END;
CREATE TRIGGER fb_banking_banklinestatus_kept BEFORE DELETE ON banking_banklinestatus BEGIN SELECT RAISE(ABORT,'banking_kept: Banking history is never deleted'); END;
CREATE TRIGGER fb_banking_reconciliationline_collision_insert BEFORE INSERT ON banking_reconciliationline BEGIN SELECT RAISE(ABORT,'banking_key_collision: Protected key already exists') WHERE EXISTS(SELECT 1 FROM banking_reconciliationline WHERE (id=NEW.id) OR (reconciliation_id=NEW.reconciliation_id AND journal_line_id=NEW.journal_line_id)); END;
CREATE TRIGGER fb_banking_reconciliationline_primary_key_permanent BEFORE UPDATE OF id ON banking_reconciliationline WHEN NEW.id IS NOT OLD.id BEGIN SELECT RAISE(ABORT,'primary_key_immutable: Primary keys never change'); END;
CREATE TRIGGER fb_banking_reconciliationline_immutable_update BEFORE UPDATE ON banking_reconciliationline BEGIN SELECT RAISE(ABORT,'banking_immutable: Banking history is immutable'); END;
CREATE TRIGGER fb_banking_reconciliationline_kept BEFORE DELETE ON banking_reconciliationline BEGIN SELECT RAISE(ABORT,'banking_kept: Banking history is never deleted'); END;
