CREATE TRIGGER fb_banking_seal_primary_key_permanent BEFORE UPDATE OF kind,doc_id ON banking_seal WHEN NEW.kind IS NOT OLD.kind OR NEW.doc_id IS NOT OLD.doc_id BEGIN SELECT RAISE(ABORT,'primary_key_immutable: Primary keys never change'); END;
CREATE TRIGGER fb_banking_seal_immutable_update BEFORE UPDATE ON banking_seal BEGIN SELECT RAISE(ABORT,'banking_immutable: Banking history is immutable'); END;
CREATE TRIGGER fb_banking_seal_kept BEFORE DELETE ON banking_seal BEGIN SELECT RAISE(ABORT,'banking_kept: Banking history is never deleted'); END;
