CREATE TRIGGER fb_banking_seal_due_primary_key_permanent BEFORE UPDATE OF kind,doc_id ON banking_seal_due WHEN NEW.kind IS NOT OLD.kind OR NEW.doc_id IS NOT OLD.doc_id BEGIN SELECT RAISE(ABORT,'primary_key_immutable: Primary keys never change'); END;
