CREATE TRIGGER fb_banking_one_open BEFORE INSERT ON banking_reconciliation BEGIN SELECT RAISE(ABORT,'reconciliation_one_open: One open reconciliation per account') WHERE NEW.status='OPEN' AND EXISTS(SELECT 1 FROM banking_reconciliation WHERE account_id=NEW.account_id AND status='OPEN'); END;
